"""risk contract types: Returns, VolSeries, TickerSummary, Drawdown, Report."""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class Returns:
    """Daily returns on the prices' dates after the first (`base_date`), one value per date and ticker."""

    base_date: str
    dates: tuple[str, ...]
    tickers: tuple[str, ...]
    values: Mapping[str, tuple[float, ...]]

    def __post_init__(self) -> None:
        if list(self.dates) != sorted(set(self.dates)) or self.dates[:1] <= (self.base_date,):
            raise ValueError("dates must be strictly ascending and after base_date")
        if list(self.tickers) != sorted(set(self.tickers)):
            raise ValueError("tickers must be sorted and unique")
        if set(self.values) != set(self.tickers):
            raise ValueError("values must have exactly one entry per ticker")
        for ticker in self.tickers:
            if len(self.values[ticker]) != len(self.dates):
                raise ValueError(f"{ticker}: one return per date required")


@dataclass(frozen=True)
class VolSeries:
    """Rolling volatility aligned to `returns.dates`; None until `window` earlier returns exist."""

    returns: Returns
    window: int
    annualized: bool
    values: Mapping[str, tuple[float | None, ...]]

    def __post_init__(self) -> None:
        if set(self.values) != set(self.returns.tickers):
            raise ValueError("values must have exactly one entry per ticker")
        for ticker in self.returns.tickers:
            series = self.values[ticker]
            if len(series) != len(self.returns.dates):
                raise ValueError(f"{ticker}: one value per return date required")
            if any((value is None) != (index < self.window) for index, value in enumerate(series)):
                raise ValueError(f"{ticker}: values are None exactly until `window` earlier returns")


@dataclass(frozen=True)
class TickerSummary:
    """Whole-period statistics for one ticker."""

    ticker: str
    ann_return: float
    ann_vol: float
    sharpe: float
    last_vol: float | None


@dataclass(frozen=True)
class Drawdown:
    """Worst fall from a peak; `depth` is at most 0."""

    ticker: str
    depth: float
    peak_date: str

    def __post_init__(self) -> None:
        if not self.depth <= 0:
            raise ValueError("depth must be at most 0")


@dataclass(frozen=True)
class Report:
    """The written report: one row per ticker, sorted; the same rows as the file at `path`."""

    path: str
    rows: tuple[Mapping[str, object], ...]

