"""PL-02 step 3: rolling volatility (spine: expanding stdev of earlier returns)."""

from __future__ import annotations

from statistics import stdev

from risk.types import Returns, VolSeries


def rolling_vol(returns: Returns, window: int) -> VolSeries:
    """Per date, the sample stdev of all earlier returns; None until `window` of them exist."""
    if window < 2:
        raise ValueError("window must be at least 2")
    values = {
        ticker: tuple(
            None if index < window else stdev(series[:index]) for index in range(len(series))
        )
        for ticker, series in returns.values.items()
    }
    return VolSeries(returns=returns, window=window, annualized=False, values=values)

