from __future__ import annotations

import pytest

from risk import vol_pipeline
from risk.types import Returns, VolSeries


@pytest.fixture
def fake_prices(monkeypatch, contract_fake):
    monkeypatch.setattr(
        vol_pipeline, "load_prices", contract_fake("mdata.load_prices").load_prices
    )


@pytest.mark.usefixtures("fake_prices")
def test_vol_series_runs_end_to_end():
    vol = vol_pipeline.vol_series("prices.csv", window=2)
    assert isinstance(vol, VolSeries)
    assert vol.annualized is True
    assert vol.window == 2
    assert vol.returns.tickers == ("AAPL", "MSFT")
    assert len(vol.returns.dates) == 5
    assert {ticker: len(series) for ticker, series in vol.values.items()} == {
        "AAPL": 5,
        "MSFT": 5,
    }
    assert vol.values["AAPL"][:2] == (None, None)


@pytest.mark.usefixtures("fake_prices")
def test_vol_series_narrows_to_the_requested_tickers():
    vol = vol_pipeline.vol_series("prices.csv", window=2, tickers=["MSFT"])
    assert vol.returns.tickers == ("MSFT",)
    assert set(vol.values) == {"MSFT"}


@pytest.mark.usefixtures("fake_prices")
def test_vol_series_rejects_a_window_below_two():
    with pytest.raises(ValueError, match="at least 2"):
        vol_pipeline.vol_series("prices.csv", window=1)


def _returns(payload):
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={ticker: tuple(series) for ticker, series in payload["values"].items()},
    )


def test_contract_samples_build_their_types(contract_sample):
    returns = _returns(contract_sample("risk.Returns"))
    payload = contract_sample("risk.VolSeries")
    vol = VolSeries(
        returns=_returns(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={ticker: tuple(series) for ticker, series in payload["values"].items()},
    )
    assert returns.tickers == ("AAPL", "MSFT")
    assert len(returns.dates) == 5
    assert vol.returns == returns
    assert vol.window == 2
    assert vol.annualized is True

